import AppKit
import SwiftUI

struct NativeMinecraftDownloadsView:View {
    @ObservedObject var model:LauncherModel
    @State private var filter="release"
    @State private var query=""
    
    var filtered:[RemoteGame]{model.remote.filter{(filter=="all" || $0.type==filter) && (query.isEmpty || $0.id.localizedCaseInsensitiveContains(query))}}
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:22){HStack{Text("下载").font(.system(size:34,weight:.semibold));Spacer();if model.cachedCatalog{Text("离线缓存").font(.system(size:11)).foregroundStyle(.secondary)};Button{Task{await model.fetchCatalog()}}label:{Image(systemName:"arrow.clockwise")}.buttonStyle(HarborButtonStyle())}
        HStack{Picker("版本",selection:$filter){Text("正式版").tag("release");Text("快照").tag("snapshot");Text("全部").tag("all")}.pickerStyle(.segmented).frame(width:270);Spacer();TextField("搜索版本",text:$query).textFieldStyle(.roundedBorder).frame(width:180)}
        if model.loadingCatalog{ProgressView().frame(maxWidth:.infinity,minHeight:180)}
        LazyVStack(spacing:0){ForEach(filtered){version in HStack{VStack(alignment:.leading,spacing:4){Text(version.id).font(.system(size:18,weight:.medium));Text(version.releaseTime?.prefix(10) ?? "").font(.system(size:11,design:.monospaced)).foregroundStyle(.secondary)};Spacer();Button("安装"){model.modal = .install(version)}.buttonStyle(HarborButtonStyle())}.padding(17);if version.id != filtered.last?.id{Divider().opacity(0.35)}}}.harborGlass(appearance:model.appearance,radius:23)
        if !model.works.isEmpty{Text("任务").font(.system(size:20,weight:.semibold));ForEach(model.works){work in VStack(alignment:.leading,spacing:9){HStack{Text(work.title).font(.system(size:13,weight:.medium));Spacer();if work.active{Button("取消"){model.cancel(work)}.font(.system(size:11))}else{Image(systemName:work.error ? "exclamationmark.circle":"checkmark.circle").foregroundStyle(work.error ? Color.orange:Color.secondary)}};if let progress=work.progress{ProgressView(value:progress)}else if work.active{ProgressView().controlSize(.small)};if !work.detail.isEmpty{Text(work.detail).font(.system(size:10)).foregroundStyle(.secondary).lineLimit(2)}}.padding(18).harborGlass(appearance:model.appearance,radius:18)}}
    }.padding(28)}.scrollIndicators(.hidden).onChange(of:filter){_,_ in HarborAudio.shared.play(.navigate)}.task{if model.remote.isEmpty{await model.fetchCatalog()}}}
}
struct InstallSheet:View {
    @ObservedObject var model:LauncherModel
    let version:RemoteGame
    
    @State private var name=""
    @State private var loader="vanilla"
    @State private var loaderVersion=""
    @State private var available:[String]=[]
    var body:some View{VStack(alignment:.leading,spacing:24){HStack{Text("安装 "+version.id).font(.system(size:27,weight:.semibold));Spacer();Button{model.modal=nil}label:{Image(systemName:"xmark")}.buttonStyle(HarborButtonStyle())};TextField("名称",text:$name).textFieldStyle(.roundedBorder);Picker("加载器",selection:$loader){Text("原版").tag("vanilla");Text("Fabric").tag("fabric");Text("Quilt").tag("quilt");Text("Forge").tag("forge");Text("NeoForge").tag("neoforge")}.onChange(of:loader){_,value in available=[];if value != "vanilla"{model.backend("loaders",title:"读取加载器",arguments:["version":version.id,"loader":value]){result in available=result["versions"] as? [String] ?? [];loaderVersion=available.first ?? ""}}};if loader != "vanilla"{Picker("版本",selection:$loaderVersion){if available.isEmpty{Text("读取中…").tag("")}else{ForEach(available,id:\.self){Text($0).tag($0)}}}};HStack{Spacer();Button("取消"){model.modal=nil}.buttonStyle(HarborButtonStyle());Button("安装"){model.install(version,name:name,loader:loader,loaderVersion:loaderVersion);model.modal=nil}.buttonStyle(HarborButtonStyle(prominent:true)).disabled(name.isEmpty || (loader != "vanilla" && loaderVersion.isEmpty))}}.padding(30).onAppear{name=version.id}}
}
struct AccountLoginControls:View {
    @ObservedObject var model:LauncherModel
    var body:some View{VStack(alignment:.leading,spacing:20){
        HStack(spacing:12){Button{model.loginMicrosoft()}label:{Label("Microsoft 登录",systemImage:"person.badge.key")}.buttonStyle(HarborButtonStyle(prominent:true)).controlSize(.large);Button("添加离线账号"){model.modal = .offline}.buttonStyle(HarborButtonStyle()).controlSize(.large)}
        if let code=model.deviceCode{VStack(alignment:.leading,spacing:16){Text("Microsoft 登录").font(.system(size:19,weight:.semibold));Text(code).font(.system(size:38,weight:.medium,design:.monospaced)).textSelection(.enabled);HStack{Button("打开验证页面"){if let value=model.verificationURL,let url=URL(string:value){NSWorkspace.shared.open(url)}}.buttonStyle(HarborButtonStyle(prominent:true));Button("复制验证码"){NSPasteboard.general.clearContents();NSPasteboard.general.setString(code,forType:.string)}};ProgressView().controlSize(.small)}.padding(24).harborGlass(appearance:model.appearance,radius:24)}

    }}
}
struct NativeSettingsView:View {
    @ObservedObject var model:LauncherModel
    @State private var tab="外观"
    let tabs=["外观","欢迎动画","运行","维护"]
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:24){HStack{Text("设置").font(.system(size:34,weight:.semibold));Spacer();Picker("设置",selection:$tab){ForEach(tabs,id:\.self){Text($0)}}.pickerStyle(.segmented).frame(width:355)}
        switch tab {
        case "外观":appearance
        case "欢迎动画":welcome
        case "运行":runtime
        default:maintenance
        }
    }.padding(28)}.scrollIndicators(.hidden).onChange(of:tab){_,_ in HarborAudio.shared.play(.navigate)}}
    private var appearance:some View{VStack(alignment:.leading,spacing:22){themePalette;glassGroup("外观"){HStack(spacing:12){ForEach(HarborAppearance.allCases){appearance in Button{model.preferences.appearance=appearance}label:{VStack(spacing:12){RoundedRectangle(cornerRadius:14).fill(appearance == .dark ? Color(hex:0x1D2521):appearance == .light ? Color(hex:0xF0F2F4):Color.white.opacity(0.08)).frame(height:62).glassEffect(appearance == .ultraClear ? .clear:.regular,in:.rect(cornerRadius:14)).overlay(OpticalRim(radius:14,strength:appearance == .ultraClear ? 0.6:0.2,color:model.themeColor,clarity:model.surfaceClarity));HStack{Text(appearance.title);Spacer();if model.appearance==appearance{Image(systemName:"checkmark.circle.fill").foregroundStyle(model.themeColor)}}.font(.system(size:12))}.padding(12).frame(maxWidth:.infinity).background(Color.primary.opacity(model.appearance==appearance ? 0.04:0),in:RoundedRectangle(cornerRadius:20)).contentShape(Rectangle())}.buttonStyle(HarborPressButtonStyle(pressedScale:0.97,pressedOffset:0))}}}
        glassGroup("背景"){Toggle("流体背景",isOn:$model.preferences.fluidBackground);HStack{Button("选择图片或视频…"){model.selectWallpaper()}.buttonStyle(HarborButtonStyle());if model.preferences.wallpaper.kind != .harbor{Button("恢复默认"){model.preferences.wallpaper.kind = .harbor;model.preferences.wallpaper.filePath=nil}.buttonStyle(HarborButtonStyle())}};settingSlider("玻璃通透",value:$model.preferences.glassClarity,range:-1...1);Toggle("玻璃色散",isOn:$model.preferences.rainbowCorners);settingSlider("窗口透明",value:$model.preferences.wallpaper.transparency,range:0...1);settingSlider("壁纸柔化",value:$model.preferences.wallpaper.blur,range:0...18);settingSlider("后景材质",value:$model.preferences.wallpaper.backdropBlur,range:0...40)}
        glassGroup("动态与声音"){Toggle("减少动态效果",isOn:$model.preferences.reduceMotion);Toggle("界面音效",isOn:$model.preferences.soundsEnabled);settingSlider("音效音量",value:$model.preferences.soundVolume,range:0...1);Button("试听"){HarborAudio.shared.play(.open)}.buttonStyle(HarborButtonStyle())}
    }}
    private var themePalette:some View { glassGroup("主题色") { HStack(spacing:15) { ForEach(["#29825B","#57A884","#81974C","#52685A","#A7834C","#8E687F"],id:\.self){hex in Button{model.preferences.themeHex=hex}label:{Circle().fill(Color(hexString:hex)).frame(width:30,height:30).overlay(Circle().strokeBorder(.white.opacity(0.8),lineWidth:model.preferences.themeHex==hex ? 3:0)).padding(3).overlay(Circle().stroke(Color.primary.opacity(model.preferences.themeHex==hex ? 0.35:0),lineWidth:0.8))}.buttonStyle(HarborBareButtonStyle()).accessibilityLabel(hex)};Spacer();ColorPicker("调色盘",selection:Binding(get:{model.themeColor},set:{model.preferences.themeHex=$0.hexString}),supportsOpacity:false).labelsHidden() } } }
    private var welcome:some View{VStack(alignment:.leading,spacing:22){glassGroup("启动欢迎"){Toggle("播放欢迎动画",isOn:$model.preferences.introEnabled);HStack{Text("显示名字");Spacer();TextField("用户名",text:$model.preferences.username).textFieldStyle(.roundedBorder).frame(width:220)};Toggle("英文女声播报",isOn:$model.preferences.voiceEnabled);settingSlider("声音",value:$model.preferences.introVolume,range:0...1);settingSlider("动画时长",value:$model.preferences.introDuration,range:3.8...7);Button("预览"){model.showIntro=true}.buttonStyle(HarborButtonStyle(prominent:true))};Text("欢迎，\(model.preferences.username)").font(.system(size:43,weight:.semibold)).tracking(-1).padding(.vertical,24)}}
    private var runtime:some View{VStack(alignment:.leading,spacing:22){glassGroup("游戏"){HStack{Text("游戏库");Spacer();if model.preferences.knownLibraries.count>1{Picker("目录",selection:$model.preferences.gameRoot){ForEach(model.preferences.knownLibraries,id:\.self){Text($0).tag($0)}}.labelsHidden().onChange(of:model.preferences.gameRoot){_,_ in model.scan()}};Text(model.preferences.gameRoot).font(.system(size:10,design:.monospaced)).foregroundStyle(.secondary).lineLimit(1);Button("选择…"){model.selectRoot()}.buttonStyle(HarborButtonStyle())};HStack{Text("最大内存");Spacer();Picker("内存",selection:$model.preferences.memory){ForEach([2048,3072,4096,5120,6144],id:\.self){Text("\($0/1024) GB").tag($0)}}.frame(width:140).labelsHidden()};HStack{Text("Java");Spacer();TextField("Java 路径",text:$model.preferences.javaPath).textFieldStyle(.roundedBorder).font(.system(size:10,design:.monospaced)).frame(width:430)}};glassGroup("前置补全"){Toggle("前置补全",isOn:$model.preferences.completeDependencies);Text("启动前检查必需模组，按版本与加载器补齐后再启动。").font(.system(size:11)).foregroundStyle(.secondary)};glassGroup("下载"){Picker("优先来源",selection:$model.preferences.downloadSource){Text("自动").tag("auto");Text("官方优先").tag("official");Text("镜像优先").tag("mirror")};Stepper("并发数  \(model.preferences.downloadThreads)",value:$model.preferences.downloadThreads,in:4...24,step:2)}}}
    private var maintenance:some View{VStack(alignment:.leading,spacing:22){glassGroup("维护"){if !model.migrationStatus.isEmpty{Text(model.migrationStatus).font(.system(size:12)).foregroundStyle(.secondary)};HStack{Button("检查下载连接"){model.diagnostics()}.buttonStyle(HarborButtonStyle());Button("打开应用数据"){model.open(NativePaths.root.path)}.buttonStyle(HarborButtonStyle());Button("备份当前存档"){if let game=model.selected{model.backup(game)}}.buttonStyle(HarborButtonStyle()).disabled(model.selected==nil)};if !model.logLines.isEmpty{Text(model.logLines.suffix(15).joined(separator:"\n")).font(.system(size:11,design:.monospaced)).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading)}};glassGroup("关于"){Text("MC Harbor").font(.system(size:24,weight:.semibold));Link("界面音效 · JDSherbert",destination:URL(string:"https://jdsherbert.itch.io/ultimate-ui-sfx-pack")!).buttonStyle(HarborBareButtonStyle()).font(.system(size:11));Text("原生 macOS · 1.4.0\nHMCL 3.16.4 内核\nCopyright © huangyuhui and contributors · GPLv3").font(.system(size:11)).foregroundStyle(.secondary);Text("便携模式：在应用旁创建 MCHarbor.portable，数据保存在旁边的 MCHarborData。").font(.system(size:11)).foregroundStyle(.secondary)}}}
    private func settingSlider(_ title:String,value:Binding<Double>,range:ClosedRange<Double>)->some View{HStack(spacing:20){Text(title).frame(width:90,alignment:.leading);Slider(value:value,in:range);Text(String(format:range.lowerBound<0 ? "%+.0f":"%.0f",value.wrappedValue*(range.upperBound==1 ? 100:1))).font(.system(size:11,design:.monospaced)).foregroundStyle(.secondary).frame(width:36)}}
    private func glassGroup<Content:View>(_ title:String,@ViewBuilder content:()->Content)->some View{VStack(alignment:.leading,spacing:18){Text(title).font(.system(size:17,weight:.semibold));content().font(.system(size:13))}.padding(24).frame(maxWidth:.infinity,alignment:.leading).harborGlass(appearance:model.appearance,radius:24)}
}
